@Test
void missingObjectWritesReportBeforeExplicitDegradedStartupAndReadsUnavailableMarker() throws Exception {
    var database = directory.resolve("degraded.db");
    var artifactRoot = directory.resolve("degraded-artifacts");
    var report = directory.resolve("degraded-validation.json");
    var scope = new ArtifactScope("host", "workspace", "session");
    ArtifactReceipt receipt;
    try (var host = new PersistentHostStore(new SqliteHostStorePersistence(database));
         var raw = new FileArtifactStore(artifactRoot, ArtifactLimits.defaults())) {
        host.create("session", new ModelRef("profile", "model"), "workspace", Instant.EPOCH);
        var lifecycle = new HostArtifactLifecycle(host, raw, report);
        lifecycle.validate(false);
        receipt = new HostArtifactStore(raw, lifecycle).putDirect(new DirectUpload(
                scope, "text/plain", "value.txt", "value".getBytes(StandardCharsets.UTF_8)), Instant.EPOCH);
    }
    java.nio.file.Path object = artifactRoot.resolve("objects")
            .resolve(receipt.artifactId().hex().substring(0, 2)).resolve(receipt.artifactId().hex());
    java.nio.file.Files.delete(object);
    try (var host = new PersistentHostStore(new SqliteHostStorePersistence(database));
         var raw = new FileArtifactStore(artifactRoot, ArtifactLimits.defaults())) {
        var rejected = new HostArtifactLifecycle(host, raw, report);
        assertThrows(io.github.diodeme.ji.artifact.fs.ArtifactStartupException.class,
                () -> rejected.validate(false));
        assertTrue(java.nio.file.Files.readString(report).contains(receipt.artifactId().value()));

        var degraded = new HostArtifactLifecycle(host, raw, report);
        degraded.validate(true);
        var store = new HostArtifactStore(raw, degraded);
        ArtifactError failure = assertThrows(ArtifactError.class,
                () -> store.read(receipt.artifactId(), scope, new ByteRange(0, 0)));
        assertEquals("artifact.unavailable", failure.code());
    }
}

